// Keep only press releases about new ventures, send them in ONE request.
const KEYWORDS = /ausgr[üu]ndung|spin-?off|start-?up|gr[üu]nderteam|gr[üu]ndungsteam|\bexist\b|gegr[üu]ndet|neugr[üu]ndung/i;
const items = $input.all()
  .map((i) => i.json)
  .filter((j) => KEYWORDS.test(`${j.title || ''} ${j.contentSnippet || ''} ${j.content || ''}`))
  .map((j) => ({
    source: 'press_release',
    url: j.link,
    date: j.isoDate || j.pubDate,
    title: j.title,
    text: `${j.title || ''}\n\n${j.contentSnippet || j.content || ''}`.slice(0, 15000),
  }));
return [{ json: { items, count: items.length } }];
